classification-and-regression-tree.pseudocode:
def gini(labels):
    n = len(labels)
    return 1 - sum((labels.count(c) / n) ** 2
                   for c in set(labels))

def best_split(rows, labels):
    # 모든 특성·임계값 중 가중 지니가 최소인 이진 분할
    pairs = list(zip(rows, labels))
    best = (gini(labels), None, None)
    for f in range(len(rows[0])):
        for t in sorted({r[f] for r in rows}):
            left = [y for r, y in pairs if r[f] <= t]
            right = [y for r, y in pairs if r[f] > t]
            if not left or not right:
                continue
            g = (len(left) * gini(left)
                 + len(right) * gini(right)) / len(rows)
            if g < best[0]:
                best = (g, f, t)
    return best  # (가중 불순도, 특성, 임계값)

classloader.pseudocode:
def load_class(loader, name):
    c = loader.loaded.get(name)  # 1. 이미 적재됐는지 확인
    if c is not None:
        return c
    if loader.parent is not None:  # 2. 부모에 먼저 위임
        c = load_class(loader.parent, name)
    else:
        c = bootstrap_find(name)  # 최상위: 부트스트랩
    if c is None:  # 3. 부모 실패 시 직접 탐색
        c = loader.find_class(name)
    if c is not None:
        loader.loaded[name] = c
    return c  # None이면 ClassNotFoundException

clipping.pseudocode:
def clip_polygon(poly, edges):  # Sutherland-Hodgman
    out = poly  # edges: (inside, intersect) 함수 쌍 목록
    for inside, intersect in edges:  # 경계마다 한 번씩
        inp, out = out, []
        for i in range(len(inp)):
            cur, prev = inp[i], inp[i - 1]
            if inside(cur):
                if not inside(prev):
                    out.append(intersect(prev, cur))  # 진입점
                out.append(cur)
            elif inside(prev):
                out.append(intersect(prev, cur))  # 이탈점
    return out

closeness-centrality.pseudocode:
def closeness(graph, v):
    # BFS로 v에서 각 노드까지 최단 거리 (무가중 그래프)
    dist, queue = {v: 0}, [v]
    for u in queue:
        for w in graph[u]:
            if w not in dist:
                dist[w] = dist[u] + 1
                queue.append(w)
    total = sum(dist.values())
    return (len(dist) - 1) / total if total else 0.0

